#include <print>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> v = {-1, 0, 1, 2, -1, -4};
    std::sort(v.begin(), v.end());
    int n = static_cast<int>(v.size());
    for (int i = 0; i < n - 2; ++i) {
        if (i > 0 && v[i] == v[i - 1]) continue;
        int lo = i + 1, hi = n - 1;
        while (lo < hi) {
            int s = v[i] + v[lo] + v[hi];
            if (s == 0) {
                std::println("{} + {} + {} = 0", v[i], v[lo], v[hi]);
                while (lo < hi && v[lo] == v[lo + 1]) ++lo;
                while (lo < hi && v[hi] == v[hi - 1]) --hi;
                ++lo; --hi;
            } else if (s < 0) ++lo; else --hi;
        }
    }
    return 0;
}
